class Advance {String id;double amount;DateTime date;String note;Advance({required this.id,required this.amount,required this.date,this.note=''});Map<String,dynamic> toJson()=>{'id':id,'amount':amount,'date':date.toIso8601String(),'note':note};factory Advance.fromJson(Map<String,dynamic> j)=>Advance(id:j['id'],amount:(j['amount'] as num).toDouble(),date:DateTime.parse(j['date']),note:j['note']??'');}
class Employee {String id,name,role;DateTime startDate;double salaryMonthly;List<Advance> advances;List<String> attendance;Employee({required this.id,required this.name,required this.role,required this.startDate,required this.salaryMonthly,List<Advance>? advances,List<String>? attendance}):advances=advances??[],attendance=attendance??[];int get workingDays{final n=DateTime.now();final s=DateTime(startDate.year,startDate.month,startDate.day);if(n.isBefore(s))return 0;return DateTime(n.year,n.month,n.day).difference(s).inDays+1;}double get totalAdvances=>advances.fold(0,(s,a)=>s+a.amount);int get absenceDays=>workingDays>attendance.length?workingDays-attendance.length:0;double get salaryDue=>(salaryMonthly/30*attendance.length)-totalAdvances;double get remainingSalary=>salaryMonthly-totalAdvances;Map<String,dynamic> toJson()=>{'id':id,'name':name,'role':role,'startDate':startDate.toIso8601String(),'salaryMonthly':salaryMonthly,'advances':advances.map((a)=>a.toJson()).toList(),'attendance':attendance};factory Employee.fromJson(Map<String,dynamic> j)=>Employee(id:j['id'],name:j['name'],role:j['role']??'عامل',startDate:DateTime.parse(j['startDate']),salaryMonthly:(j['salaryMonthly'] as num).toDouble(),advances:(j['advances'] as List? ?? []).map((e)=>Advance.fromJson(Map<String,dynamic>.from(e))).toList(),attendance:List<String>.from(j['attendance']??[]));}
